const win = createBrowserWindow({iconPath: options.iconPath, preloadPath: options.preloadPath, logger: options.logger, deviceMid: options.deviceMid, initialDesktopZoomLevel: options.initialDesktopZoomLevel, initialWindowSize: options.initialWindowSize, currentApplicationLocale: options.currentApplicationLocale, resolveBrowserViewOwner: options.resolveBrowserViewOwner, bootstrap: {restoreSession: options.bootstrap?.restoreSession ?? true, supportsSettings: options.bootstrap?.supportsSettings ?? true, initialWorkspacePath: options.bootstrap?.initialWorkspacePath, initialWorkspacePurpose: options.bootstrap?.initialWorkspacePurpose, unavailableWorkspacePath: options.bootstrap?.unavailableWorkspacePath}});
const label = `local-${win.webContents.id}`;
win.webContents.on('will-prevent-unload', createUnsavedChangesGuard({confirm: () => {if (win.isMinimized()) win.restore();win.show();win.focus();return dialog.showMessageBoxSync(win,unsavedChangesDialogOptions(options.currentApplicationLocale?.() ?? 'en-US')) === 1;},stay: () => options.onUnloadCancelled?.(),onError: error => options.logger.warn('[desktop-window] unsaved draft confirmation failed',error)}));
if (options.persistWindowSize) attachDesktopWindowSizePersistence(win,options.persistWindowSize,error=>options.logger.warn('[desktop-window] failed to persist main window size',error));
if (process.platform === 'darwin') win.on('close',event=>{if(handleDarwinWindowCloseRequest({win,forceQuit:options.forceQuitRef.current,label,logger:options.logger})) event.preventDefault();});
else if (options.handleBeforeClose) win.on('close',event=>{if(options.handleBeforeClose?.(win,label))event.preventDefault();});
const rendererId = win.webContents.id;
registerMainApplicationWindow(rendererId);
let generation = 0;
let cancelWait: (() => void) | undefined;
win.webContents.on('dom-ready',async()=>{
 cancelWait?.();cancelWait=undefined;const current=++generation;
 options.logger.info(`[createWindow] dom-ready fired (${label})`);
 if(process.platform==='win32'&&!win.isDestroyed()){win.show();win.focus();}
 const old=options.windowHostProcessMap.get(rendererId);
 if(old&&old.pid!==undefined){try{const startup=getDatabaseStartupPortPayload(old);if(!startup)throw new Error('Previous Host startup binding is unavailable');const {port1,port2}=new MessageChannelMain();old.postMessage({type:HostMessageTypes.AttachServicePort,requestId:randomUUID(),attachmentId:randomUUID(),clientMode:'desktop-continuous',scope:{kind:'local'}},[port2]);win.webContents.postMessage(InternalChannels.ServicePort,startup,[port1]);options.logger.info(`[createWindow] renderer reloaded, reattached to existing host (${label}), pid=${old.pid}`);options.reattachRemoteWorkspaceSessionsForWindow(win,`${label}:renderer-reload`);return;}catch(error){options.logger.warn(`[createWindow] reattach to existing host failed (${label}), falling back to respawn:`,error);}}
 if(old){options.logger.info(`[createWindow] killing previous host process for (${label}), pid=${old.pid ?? 'unknown'}`);options.disposeHostProcess(old,`${label}:reload`,150);}
 if(options.awaitFirstHostSpawnDecision)await options.awaitFirstHostSpawnDecision();
 const spawn=(patch:Record<string,string>)=>{if(current!==generation||win.isDestroyed())return;const warmup=options.agentWarmupTargets?.[0];const child=options.spawnHostProcess(win,label,{type:HostMessageTypes.InitLocal,deviceMid:options.deviceMid,workspacePath:warmup?.workspacePath,workspaceIdentity:warmup?.workspaceIdentity,runtimeProcessEnvPatch:patch,agentSpawnFallbackCwd:options.agentSpawnFallbackCwd,...(options.agentWarmupTargets?.length?{agentWarmupTargets:[...options.agentWarmupTargets]}:{})});options.windowHostProcessMap.set(rendererId,child);options.onHostProcessReady?.(rendererId);options.reattachRemoteWorkspaceSessionsForWindow(win,`${label}:renderer-ready`);};
 if(current!==generation||win.isDestroyed())return;
 if(!options.runtimeProcessEnvPatchPromise){spawn(options.runtimeProcessEnvFallbackPatch);return;}
 await new Promise<void>(resolve=>{let settled=false;let timer:ReturnType<typeof setTimeout>|undefined;const cancel=()=>{if(settled)return;settled=true;if(timer)clearTimeout(timer);resolve();};const complete=(patch:Record<string,string>)=>{if(settled)return;settled=true;if(timer)clearTimeout(timer);if(cancelWait===cancel)cancelWait=undefined;spawn(patch);resolve();};cancelWait=cancel;const timeout=options.runtimeProcessEnvWaitTimeoutMs??4500;timer=setTimeout(()=>{options.logger.warn(`[createWindow] runtime env prewarm exceeded ${timeout}ms after dom-ready (${label}), using shell-free fallback`);complete(options.runtimeProcessEnvFallbackPatch);},timeout);options.runtimeProcessEnvPatchPromise!.then(complete).catch(error=>{options.logger.warn(`[createWindow] runtime env prewarm failed (${label}), using shell-free fallback:`,error);complete(options.runtimeProcessEnvFallbackPatch);});});
});
win.on('closed',()=>{unregisterMainApplicationWindow(rendererId);cancelWait?.();cancelWait=undefined;options.logger.info(`[createWindow] window closed, killing host process (${label})`);const child=options.windowHostProcessMap.get(rendererId);if(child){options.disposeHostProcess(child,`${label}:window-closed`);options.windowHostProcessMap.delete(rendererId);}options.disposeRemoteWorkspaceSessionsForWindow(rendererId,`${label}:window-closed`);});
return win;

handleWindowUnreadCountSync:
const count=parseWindowUnreadCount(payload);
if(count==null){logger.warn('[sync-window-unread-count] invalid payload:',payload);return false;}
if(!win)return false;
if(count===0)windowUnreadCountMap.delete(win.id);else windowUnreadCountMap.set(win.id,count);
syncApplicationUnreadBadge(windowUnreadCountMap);return true;

handleDesktopWindowCloseRequest:
if(options.platform==='win32'&&options.closeToTrayOnWindows&&!options.forceQuit&&!options.explicitQuitRequested){options.logger.info(`[createWindow] window close hidden to tray (${options.label})`);options.hideWindow?.();return true;}
if(options.platform==='darwin'||options.forceQuit||!options.isLastWindow)return false;
if(options.shouldConfirmQuit===false){options.logger.info(`[createWindow] last window close skipped confirmation, quitting app (${options.label})`);options.requestQuit();return true;}
if(!options.confirmQuit()){options.logger.info(`[createWindow] last window close canceled by user (${options.label})`);return true;}
options.logger.info(`[createWindow] last window close confirmed, quitting app (${options.label})`);options.requestQuit();return true;
